private fpsCounter: Phaser.Text;
private lastUpdate: number;
private frameCount: number;

private createFpsCounter() {
    this.fpsCounter = this.game.add.text(10, 10, 'FPS: 0', { fill: '#ffffff' });
    this.fpsCounter.fixedToCamera = true;
    this.lastUpdate = 0;
    this.frameCount = 0;
}

private updateFpsCounter() {
    this.frameCount++;
    const now = this.game.time.now;
    if (now - this.lastUpdate >= 1000) {
        const fps = Math.round((this.frameCount / (now - this.lastUpdate)) * 1000);
        this.fpsCounter.setText(`FPS: ${fps}`);
        this.lastUpdate = now;
        this.frameCount = 0;
    }
}

